fn rot2(a: f32) -> mat2x2f { let c = cos(a); let s = sin(a); return mat2x2f(c, s, -s, c); }
@fragment fn fs_main(@builtin(position) fp: vec4f) -> @location(0) vec4f {
    let p = select(bench_p(fp.xy), textureSampleLevel(in0, smp, fp.xy / u.size, 0.0).xy, b.has0 > 0.5);
    let q = rot2(u.k.y * 6.2831853) * p * mix(0.25, 4.0, u.k.x) + (vec2f(u.k.z, u.k.w) - vec2f(0.5)) * 2.0;
    return vec4f(q, 0.0, 1.0);
}

warp.code:
// resample the image through a coordinate: the texture-graph form of domain warping
@fragment fn fs_main(@builtin(position) fp: vec4f) -> @location(0) vec4f {
    let q = textureSampleLevel(in1, smp, fp.xy / u.size, 0.0).xy;
    return textureSampleLevel(in0, smp, q * 0.5 + 0.5, 0.0);
}

displace.code:
// push the image around by a field: two samples of the field give the x and y offsets
@fragment fn fs_main(@builtin(position) fp: vec4f) -> @location(0) vec4f {
    let uv = fp.xy / u.size;
    let f = textureSampleLevel(in1, smp, uv, 0.0).r; let g = textureSampleLevel(in1, smp, uv + vec2f(0.37, 0.11), 0.0).r;
    return textureSampleLevel(in0, smp, uv + u.k.x * 0.3 * (vec2f(f, g) - vec2f(0.5)), 0.0);
}

